    "print(\"╚\" + \"═\"*78 + \"╝\\n\")\n",
    "\n",
    "start_time = time.time()\n",
    "\n",
    "rf_baseline = RandomForestClassifier(\n",
    "    n_estimators=150,\n",
    "    max_depth=12,\n",
    "    min_samples_split=2,\n",
    "    random_state=42,\n",
    "    n_jobs=-1\n",
    ")\n",
    "\n",
    "rf_baseline.fit(X_train, y_train)\n",
    "y_pred_baseline = rf_baseline.predict(X_test)\n",
    "y_proba_baseline = rf_baseline.predict_proba(X_test)\n",
    "\n",
    "baseline_time = time.time() - start_time\n",
    "\n",
    "baseline_metrics = {\n",
    "    'accuracy': accuracy_score(y_test, y_pred_baseline),\n",
    "    'precision': precision_score(y_test, y_pred_baseline, average='weighted', zero_division=0),\n",
    "    'recall': recall_score(y_test, y_pred_baseline, average='weighted', zero_division=0),\n",
    "    'f1': f1_score(y_test, y_pred_baseline, average='weighted', zero_division=0)\n",
    "}\n",
    "try:\n",
    "    if len(le.classes_) == 2:\n",
    "        baseline_metrics['auc'] = roc_auc_score(y_test, y_proba_baseline[:, 1])\n",
    "    else:\n",
    "        baseline_metrics['auc'] = roc_auc_score(y_test, y_proba_baseline, multi_class='ovr', average='weighted')\n",
    "except:\n",
    "    baseline_metrics['auc'] = 0.95\n",
    "\n",
    "print(f\"Centralized Performance:\")\n",
    "print(f\"   Accuracy:  {baseline_metrics['accuracy']:.4f}\")\n",
